def get_doctype(
    path: Path,
) -> tuple[type[types.Parser], str] | tuple[None, None]:
    """
    Gets the appropriate doctype for *path*.

    Returns:
        Tuple of parser type and the name of the documentation.
    """
    for dt in DOCTYPES:
        name = dt.detect(path)
        if name:
            return dt, name
    else:
        return None, None

